$ErrorActionPreference='Stop'
Set-StrictMode -Version 2.0
$out=$PSScriptRoot;$code=1;$stage='registered-current-user-official-Store-package'
function Need([bool]$v,[string]$label){if(-not $v){throw $label}}
function Hash([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
function Save([string]$name,$value){[IO.File]::WriteAllText((Join-Path $out $name),(ConvertTo-Json -InputObject $value -Depth 12)+"`n",[Text.UTF8Encoding]::new($false))}
try{
 $packages=@(Get-AppxPackage -Name '*Claude*' -ErrorAction Stop);Need ($packages.Count -eq 1) 'current-Claude-package-not-unique';$pkg=$packages[0]
 Need ($pkg.Name -ceq 'AnthropicPBC.Claude' -and $pkg.Version.ToString() -ceq '5.11492.5.0' -and $pkg.Status.ToString() -ceq 'Ok' -and $pkg.SignatureKind.ToString() -ceq 'Store') 'actual-registered-Store-version-or-trust-mismatch'
 $manifest=Get-AppxPackageManifest -Package $pkg -ErrorAction Stop
 $apps=@($manifest.Package.Applications.Application);$appMetadata=@($apps|ForEach-Object {[ordered]@{id=$_.Id;executable=$_.Executable;entryPoint=$_.EntryPoint}})
 $stage='actual-installed-native-EXE-and-ASAR'
 $exes=@(Get-ChildItem -LiteralPath $pkg.InstallLocation -Filter 'Claude.exe' -File -Recurse -ErrorAction Stop);$asars=@(Get-ChildItem -LiteralPath $pkg.InstallLocation -Filter 'app.asar' -File -Recurse -ErrorAction Stop)
 Need ($exes.Count -eq 1 -and $asars.Count -eq 1) 'actual-installed-EXE-or-ASAR-not-unique';$exe=$exes[0];$asar=$asars[0]
 Need ($exe.Length -gt 10000000 -and $asar.Length -gt 1000000) 'actual-installed-native-files-incomplete'
 $sig=Get-AuthenticodeSignature -LiteralPath $exe.FullName;Need ($sig.Status.ToString() -ceq 'Valid' -and $sig.SignerCertificate.GetNameInfo([Security.Cryptography.X509Certificates.X509NameType]::SimpleName,$false) -ceq 'Anthropic, PBC') 'actual-installed-native-Anthropic-signature-invalid'
 $stage='installed-public-package-ASAR-version'
 $f=[IO.File]::Open($asar.FullName,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite);$br=[IO.BinaryReader]::new($f)
 try{Need ($br.ReadUInt32() -eq 4) 'asar-first-pickle-invalid';$headerSize=$br.ReadUInt32();$pickleSize=$br.ReadUInt32();$jsonSize=$br.ReadUInt32();Need ($headerSize -lt 20000000 -and $jsonSize -lt $headerSize -and $jsonSize -gt 0) 'asar-header-size-invalid';$header=[Text.Encoding]::UTF8.GetString($br.ReadBytes($jsonSize))|ConvertFrom-Json;$entry=$header.files.PSObject.Properties['package.json'].Value;Need ($null -ne $entry -and -not $entry.PSObject.Properties['unpacked'] -and [int]$entry.size -gt 0 -and [int]$entry.size -lt 1000000) 'asar-public-package-json-invalid';$f.Position=8+[int64]$headerSize+[int64]$entry.offset;$packageJson=[Text.Encoding]::UTF8.GetString($br.ReadBytes([int]$entry.size))|ConvertFrom-Json;Need ($packageJson.version -ceq '5.11492.5') 'installed-ASAR-package-version-mismatch'}finally{$br.Dispose();$f.Dispose()}
 $r=[ordered]@{schemaVersion=1;status='official-Claude-Windows-Store-native-installation-files-and-registration-verified';observedAtUtc=[DateTime]::UtcNow.ToString('o');actualNativeExitCode=0;nativeInstallerExitCode=0;officialStoreProductId='9P6K58THS811';officialStorePublisherName='Anthropic, PBC';currentUserScope=$true;registeredPackageName=$pkg.Name;registeredPackageVersion=$pkg.Version.ToString();registeredPackageFullName=$pkg.PackageFullName;registeredPackageFamilyName=$pkg.PackageFamilyName;registeredPackageStatus=$pkg.Status.ToString();registeredPackageSignatureKind=$pkg.SignatureKind.ToString();registeredPackagePublisher=$pkg.Publisher;installationRoot=$pkg.InstallLocation;actualAppManifestApplications=$appMetadata;actualAppxManifestSha256=(Hash (Join-Path $pkg.InstallLocation 'AppxManifest.xml'));actualInstalledExe=$exe.FullName;actualInstalledExeBytes=$exe.Length;actualInstalledExeSha256=(Hash $exe.FullName);actualInstalledExeAuthenticodeStatus=$sig.Status.ToString();actualInstalledExeSignerSubject=$sig.SignerCertificate.Subject;actualInstalledExeSignerSimpleName=$sig.SignerCertificate.GetNameInfo([Security.Cryptography.X509Certificates.X509NameType]::SimpleName,$false);actualInstalledExeSignerThumbprint=$sig.SignerCertificate.Thumbprint;actualInstalledExeFileVersion=$exe.VersionInfo.FileVersion;actualInstalledExeProductVersion=$exe.VersionInfo.ProductVersion;actualInstalledAsar=$asar.FullName;actualInstalledAsarBytes=$asar.Length;actualInstalledAsarSha256=(Hash $asar.FullName);actualInstalledAsarPackageName=$packageJson.name;actualInstalledAsarPackageVersion=$packageJson.version;nativeInstallerTerminalProofSha256=(Hash (Join-Path $out 'winget-store-install-terminal-safe.json'));nativeInstallationRegistrationProofSha256=(Hash (Join-Path $out 'winget-store-installed-registration-safe.json'));storeInternalLicensingTransportNotIndependentlyObserved=$true;priorFailedSquirrelPartialFilesPreserved=$true;explicitGuiLaunches=0;explicitLoginActions=0;modelCalls=0;privateProfileConfigurationAuthOrUserDataRead=$false;sharedWorkerOperations=0;processSignals=0;forcedTerminations=0}
 Save 'installed-windows-native-final-safe.json' $r;$r|ConvertTo-Json -Depth 12;$code=0
}catch{$r=[ordered]@{status='installed-Store-package-native-file-verification-incomplete';observedAtUtc=[DateTime]::UtcNow.ToString('o');stage=$stage;errorType=$_.Exception.GetBaseException().GetType().FullName;staticCode=if($_.Exception.GetBaseException().Message -match '^[a-zA-Z0-9-]+$'){$_.Exception.GetBaseException().Message}else{$null};privateProfileContentsRead=$false;processSignals=0};Save 'installed-windows-verification-failure-safe.json' $r;$r|ConvertTo-Json -Depth 12}
exit $code
